import{_ as t}from"./chunks/maintenance-pwr.pc.en.CVW_nHka.js";import{_ as o,o as n,c as a,a5 as r}from"./chunks/framework.BYXPg_yw.js";const w=JSON.parse('{"title":"Powering the external ports","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/interface/port-power.md","filePath":"manual/interface/port-power.md","lastUpdated":1792759058000}'),i={name:"manual/interface/port-power.md"};function s(c,e,l,h,d,p){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="powering-the-external-ports" tabindex="-1">Powering the external ports <a class="header-anchor" href="#powering-the-external-ports" aria-label="Permalink to &quot;Powering the external ports&quot;">​</a></h1><p>If a payload wired into an external port does nothing, the usual reason is that <strong>the port&#39;s power is off</strong>. Plugging the connector in does not energise the port — <strong>you switch it on in the app</strong>.</p><p>Wiring and pin assignments are in <a href="/RBQ/nightly/manual/interface/external-port.html">External ports</a>; the cables are listed under <a href="/RBQ/nightly/manual/product-descriptions/accessories.html#payload-cabling">Accessories</a>.</p><h2 id="where" tabindex="-1">Where to switch it on <a class="header-anchor" href="#where" aria-label="Permalink to &quot;Where to switch it on {#where}&quot;">​</a></h2><p>All external port power is switched in <strong>Maintenance → Power / System</strong>, which everyone can open. The ports you plug into from outside are gathered in the <code>Top ports</code> section. The whole screen is described in <a href="/RBQ/nightly/manual/gui/maintenance.html#power">Maintenance › Power / System</a>.</p><p><img src="'+t+'" alt="Maintenance → Power / System"></p><h2 id="48v" tabindex="-1">Switching on a 48 V port <a class="header-anchor" href="#48v" aria-label="Permalink to &quot;Switching on a 48 V port {#48v}&quot;">​</a></h2><p>Ports that carry raw battery voltage — <code>POWER</code> (2-pin) and <code>PWR-CAN</code> (4-pin) — sit on the 48 V rails.</p><ol><li>Open <strong>Maintenance → Power / System</strong>.</li><li>Press <strong><code>Turn on</code></strong> on the <code>EXTERN (48V)</code> row in the <code>Top ports</code> section — the power that goes out to the external expansion ports. CAN-FD robots have no such row, only <code>ARM · ADDON (48V)</code>.</li><li>Confirm with <strong><code>Turn on</code></strong> in the <code>Turn this on?</code> dialog.</li><li>Check that the <strong>live voltage</strong> on that row comes up.</li></ol><p>If your add-on sits on <code>ARM · ADDON (48V)</code>, switch that row instead.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p><code>ARM · ADDON (48V)</code> is <strong>one PDU port shared</strong> by the arm and the add-on. Turning this rail off also cuts arm power, so make sure the arm is stopped before you switch it.</p></div></div><p>The 48 V rails put out <strong>raw battery voltage</strong>, which moves between 42.0 V and 58.4 V with the state of charge. Add your own converter if the payload needs a regulated supply.</p><h2 id="12v" tabindex="-1">Switching on a 12 V port <a class="header-anchor" href="#12v" aria-label="Permalink to &quot;Switching on a 12 V port {#12v}&quot;">​</a></h2><p>Tap the <code>12V port 1</code>–<code>4</code> toggles in the <code>Top ports</code> section. The ports are named by number only, because what is plugged into them differs from robot to robot. A picture of which connector is which will be added under <code>? Help</code> next to the section title. Turning a port off asks <code>Turn this off?</code> first — if a network device is plugged into it, the app may lose its connection.</p><h2 id="not-working" tabindex="-1">It is on but still does not work <a class="header-anchor" href="#not-working" aria-label="Permalink to &quot;It is on but still does not work {#not-working}&quot;">​</a></h2><ul><li><strong>The toggle is grayed out and will not press</strong> — the rail state has not arrived yet. Check the robot connection first (<a href="/RBQ/nightly/manual/gui/connection.html">Connection</a>).</li><li><strong>It does not flip immediately</strong> — the toggle shows the <strong>actual state</strong> the robot&#39;s PDU reports, and that takes about a second to come back.</li><li><strong>The voltage does not come up</strong> — check that the connector is seated and the cable is intact (<a href="/RBQ/nightly/manual/maintenance/connector.html">Connector handling</a>).</li><li><strong>Power is present but the device stays off</strong> — check you are within the per-port current limit: <code>POWER</code> 5 A, <code>PWR-CAN</code> 10 A, <code>12V/LAN</code> 2–3 A (<a href="/RBQ/nightly/manual/interface/external-port.html#user-port-pin-map">pin map</a>).</li></ul><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck {#still-stuck}&quot;">​</a></h2><p>Tell us which port you wired what into, and the voltage shown on the power screen.</p><p><strong>→ <a href="/RBQ/nightly/manual/support/">Support</a></strong></p>',19)])])}const m=o(i,[["render",s]]);export{w as __pageData,m as default};
